# Preserve the complete source text in a clearly labelled appendix. Citation IDs remain in the downloadable original.
def clean(s):
 s=re.sub(r'\ue200cite\ue202.*?\ue201','',s)
 for a,b in [('ё','е'),('Ё','Е'),('—','-'),('–','-'),('«','"'),('»','"'),('“','"'),('”','"'),('‘',"'"),('’',"'"),(';',',')]:s=s.replace(a,b)
 return s

def inline(s):
 s=html.escape(clean(s))
 s=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 return s

def markdown(text):
 lines=text.splitlines();res=[];i=0
 while i<len(lines):
  line=lines[i].strip()
  if not line:i+=1;continue
  if line.startswith('|'):
   rows=[]
   while i<len(lines) and lines[i].strip().startswith('|'):
    cells=lines[i].strip().strip('|').split('|')
    if not all(re.fullmatch(r'\s*[:\-]+\s*',c) for c in cells):rows.append(cells)
    i+=1
   res.append('<div class="table-wrap"><table>'+''.join('<tr>'+''.join(('<th>' if n==0 else '<td>')+inline(c.strip())+('</th>' if n==0 else '</td>') for c in row)+'</tr>' for n,row in enumerate(rows))+'</table></div>');continue
  if line.startswith('#'):
   n=min(4,len(line)-len(line.lstrip('#'))+1);res.append(f'<h{n}>'+inline(line.lstrip('# '))+f'</h{n}>')
  else:res.append('<p>'+inline(line)+'</p>')
  i+=1
 return ''.join(res)
